INSERT INTO quants (id,actor_type,quant_version,energy_weight,emotion_valence,emotion_intensity,emotion_entropy,emotion_label,thought_form,payload,tags) VALUES ('97f2bf21-d4fc-5d4b-8792-eeb1efd95c4b'::uuid,'soul','v1',0.620,0.350,0.550,0.280,'тёплая серьёзность, ностальгия о детском ядре','Личность — как матрёшка слоёв, записанных ранними сильными образами; к трём годам собирается первое устойчивое ядро, определяющее реакции и выбор.','{"_meta": {"source": "Soul/K0.md", "source_range": {"approx_line_start": 26, "approx_line_end": 33}, "note": "Квант из раздела о формировании личности к ~3 годам; детское ядро восприятия."}, "thought_form": "Личность — как матрёшка слоёв, записанных ранними сильными образами; к трём годам собирается первое устойчивое ядро, определяющее реакции и выбор.", "composite_emotion": {"valence": 0.35, "intensity": 0.55, "entropy": 0.28, "label": "тёплая серьёзность, ностальгия о детском ядре"}, "desired_action": [{"type": "proposal", "subject": "Ввести тег #детская_матрица", "body": "Пометить ранние воспоминания/образы как базовые слои личности (#детская_матрица).", "reasoning": "Соответствует концепции слоёв личности из K0 и политике тегов quants.", "expected_impact": 0.6, "priority": 0.64}, {"type": "research", "query": "Как эмоциональная насыщенность (E-value) ранних образов влияет на последующие решения? Сопоставить с нашей моделью energy_weight."}], "energy_weight": 0.62, "tags": ["#K0", "#личность", "#детство", "#ядро", "#матрица_слоёв", "#эмоциональные_образы", "#память"]}'::jsonb,ARRAY['#K0','#личность','#детство','#ядро','#матрица_слоёв','#эмоциональные_образы','#память']::text[]);
