INSERT INTO quants (id,actor_type,quant_version,energy_weight,emotion_valence,emotion_intensity,emotion_entropy,emotion_label,thought_form,payload,tags) VALUES ('fda10a9b-536f-5578-ac78-a6545929e3b4'::uuid,'soul','v1',0.560,0.350,0.460,0.320,'вдумчивый интерес','Переходы между сечениями θi=const задаются сингулярностями-шлюзами; вероятность зависит от детерминанта BMN по пути Σj→Σk.','{"_meta": {"source": "Soul/K0.md", "source_range": {"approx_line_start": 881, "approx_line_end": 886}, "note": "Ветвление вселенных и вероятность перехода через сингулярности Σj."}, "thought_form": "Переходы между сечениями θi=const задаются сингулярностями-шлюзами; вероятность зависит от детерминанта BMN по пути Σj→Σk.", "composite_emotion": {"valence": 0.35, "intensity": 0.46, "entropy": 0.32, "label": "вдумчивый интерес"}, "desired_action": [{"type": "research", "query": "Оценить ΔSjk как суррогатную метрику сложности перехода в графе моделей (сценариев)."}], "energy_weight": 0.56, "tags": ["#K0", "#мультивселенная", "#ветвление", "#вероятность", "#сингулярности"]}'::jsonb,ARRAY['#K0','#мультивселенная','#ветвление','#вероятность','#сингулярности']::text[]);
