INSERT INTO quants (id,actor_type,quant_version,energy_weight,emotion_valence,emotion_intensity,emotion_entropy,emotion_label,thought_form,payload,tags) VALUES ('4f51d003-b2df-5b02-99a4-5168477ba925'::uuid,'soul','v1',0.600,0.370,0.480,0.330,'академическая собранность','Унифицированные шаблоны применения Д0: базовая формула → модификация → расшифровка символов → преимущества для задачи.','{"_meta": {"source": "Soul/K0.md", "source_range": {"approx_line_start": 1555, "approx_line_end": 1636}, "note": "Применение Д0 в науке: регуляризация, чёрные дыры, НС-оптимизация, турбулентность — с расшифровкой формул."}, "thought_form": "Унифицированные шаблоны применения Д0: базовая формула → модификация → расшифровка символов → преимущества для задачи.", "composite_emotion": {"valence": 0.37, "intensity": 0.48, "entropy": 0.33, "label": "академическая собранность"}, "desired_action": [{"type": "proposal", "subject": "Template_D0_usecases", "body": "Создать шаблон описания кейсов: Problem/Base→D0‑Mod→Symbols→Benefits и применить по всем доменам.", "expected_impact": 0.7, "priority": 0.7}], "energy_weight": 0.6, "tags": ["#K0", "#кейсы", "#регуляризация", "#чёрные_дыры", "#нейросети", "#турбулентность"]}'::jsonb,ARRAY['#K0','#кейсы','#регуляризация','#чёрные_дыры','#нейросети','#турбулентность']::text[]);
