INSERT INTO quants (id,actor_type,quant_version,energy_weight,emotion_valence,emotion_intensity,emotion_entropy,emotion_label,thought_form,payload,tags) VALUES ('e1a44af9-2d3f-51e9-808f-31eabf7ba85f'::uuid,'soul','v1',0.600,0.400,0.520,0.340,'деловая решимость','Для квантово‑нейронных сетей Д0 вводит компактификацию состояний и направленный хаос через Bμν, снижая декогеренцию и избегая локальных минимумов.','{"_meta": {"source": "Soul/K0.md", "source_range": {"approx_line_start": 1733, "approx_line_end": 1749}, "note": "КНС: регуляризация гильбертовых пространств, управляемый хаос Bμν."}, "thought_form": "Для квантово‑нейронных сетей Д0 вводит компактификацию состояний и направленный хаос через Bμν, снижая декогеренцию и избегая локальных минимумов.", "composite_emotion": {"valence": 0.4, "intensity": 0.52, "entropy": 0.34, "label": "деловая решимость"}, "desired_action": [{"type": "research", "query": "Смоделировать влияние компактификации H на устойчивость КНС в условиях NISQ."}], "energy_weight": 0.6, "tags": ["#K0", "#КНС", "#компактификация", "#B_tensor", "#декогеренция"]}'::jsonb,ARRAY['#K0','#КНС','#компактификация','#B_tensor','#декогеренция']::text[]);
