INSERT INTO quants (id,actor_type,quant_version,energy_weight,emotion_valence,emotion_intensity,emotion_entropy,emotion_label,thought_form,payload,tags) VALUES ('6ebed5f0-b720-56c0-8438-0a95f23803e8'::uuid,'soul','v1',0.560,0.380,0.470,0.310,'собранная строгость','Структурирование матаппарата Д0: метрика MD, уравнения поля с Bμν, фазовые переходы и регуляризация — каждая формула снабжена полным описанием символов.','{"_meta": {"source": "Soul/K0.md", "source_range": {"approx_line_start": 1801, "approx_line_end": 1810}, "note": "Матаппарат Д0: структура раздела и ключевые формулы с расшифровкой."}, "thought_form": "Структурирование матаппарата Д0: метрика MD, уравнения поля с Bμν, фазовые переходы и регуляризация — каждая формула снабжена полным описанием символов.", "composite_emotion": {"valence": 0.38, "intensity": 0.47, "entropy": 0.31, "label": "собранная строгость"}, "desired_action": [{"type": "proposal", "subject": "Symbols_glossary_D0", "body": "Добавить глоссарий обозначений (μ,ν,i,j,k, θ, ϕ, Bμν, κ, Λ, R, Gμν) в docs."}], "energy_weight": 0.56, "tags": ["#K0", "#матаппарат", "#глоссарий", "#формулы", "#обозначения"]}'::jsonb,ARRAY['#K0','#матаппарат','#глоссарий','#формулы','#обозначения']::text[]);
