INSERT INTO quants (id,actor_type,quant_version,energy_weight,emotion_valence,emotion_intensity,emotion_entropy,emotion_label,thought_form,payload,tags) VALUES ('a9afc335-8385-5044-9147-780e6e2907a7'::uuid,'soul','v1',0.530,0.340,0.450,0.280,'техническая ясность','Метрика Д0 объединяет M_n и C; пример M4×S1 показывает регуляризацию r→0 через e^{-1/r^2} и добавочный θ‑слой.','{"_meta": {"source": "Soul/K0.md", "source_range": {"approx_line_start": 1811, "approx_line_end": 1826}, "note": "Метрика M_D и пример M4×S1: подавление сингулярности e^{-1/r^2}."}, "thought_form": "Метрика Д0 объединяет M_n и C; пример M4×S1 показывает регуляризацию r→0 через e^{-1/r^2} и добавочный θ‑слой.", "composite_emotion": {"valence": 0.34, "intensity": 0.45, "entropy": 0.28, "label": "техническая ясность"}, "desired_action": [{"type": "research", "query": "Сравнить регуляризацию e^{-1/r^2} с альтернативами (Pauli-Villars, zeta‑регуляризация) на численных примерах."}], "energy_weight": 0.53, "tags": ["#K0", "#метрика", "#регуляризация", "#пример", "#M4xS1"]}'::jsonb,ARRAY['#K0','#метрика','#регуляризация','#пример','#M4xS1']::text[]);
