INSERT INTO quants (id,actor_type,quant_version,energy_weight,emotion_valence,emotion_intensity,emotion_entropy,emotion_label,thought_form,payload,tags) VALUES ('0886aa9b-da17-5a05-8365-8fa8e691b0df'::uuid,'soul','v1',0.550,0.370,0.450,0.300,'редакционная аккуратность','Нужен протокол проверки источников: удаление дубликатов, уточнение неполных ссылок, пометка гипотетических и проверка корпоративных отчётов.','{"_meta": {"source": "Soul/K0.md", "source_range": {"approx_line_start": 1884, "approx_line_end": 1944}, "note": "Валидация литературы: протокол проверки и дедупликации ссылок."}, "thought_form": "Нужен протокол проверки источников: удаление дубликатов, уточнение неполных ссылок, пометка гипотетических и проверка корпоративных отчётов.", "composite_emotion": {"valence": 0.37, "intensity": 0.45, "entropy": 0.3, "label": "редакционная аккуратность"}, "desired_action": [{"type": "proposal", "subject": "Reference_validation_policy", "body": "Ввести шаги: dedup → fill_missing (Bardeen 1981) → corp_docs_check (IBM 2023) → flag_future (OpenAI 2025).", "expected_impact": 0.64}], "energy_weight": 0.55, "tags": ["#K0", "#литература", "#валидация", "#дедупликация", "#политика"]}'::jsonb,ARRAY['#K0','#литература','#валидация','#дедупликация','#политика']::text[]);
