INSERT INTO quants (id,actor_type,quant_version,energy_weight,emotion_valence,emotion_intensity,emotion_entropy,emotion_label,thought_form,payload,tags) VALUES ('c4cc428b-fb3b-5077-8dfc-60f7ef1f5f54'::uuid,'soul','v1',0.520,0.350,0.440,0.310,'редакционная дисциплина','Категоризация ссылок: ok (1–10,12–24), needs_fix (11,25), duplicates (3,9,18), invalid_future (26); закрепить как правило для редакции статей.','{"_meta": {"source": "Soul/K0.md", "source_range": {"approx_line_start": 1945, "approx_line_end": 2009}, "note": "Итоги проверки источников: корректные, дубликаты, неполные, гипотетические."}, "thought_form": "Категоризация ссылок: ok (1–10,12–24), needs_fix (11,25), duplicates (3,9,18), invalid_future (26); закрепить как правило для редакции статей.", "composite_emotion": {"valence": 0.35, "intensity": 0.44, "entropy": 0.31, "label": "редакционная дисциплина"}, "desired_action": [{"type": "proposal", "subject": "Fix_refs_round_1", "body": "Удалить дубликаты, дополнить 11 (полный источник), проверить/заменить 25, исключить 26.", "expected_impact": 0.62}], "energy_weight": 0.52, "tags": ["#K0", "#литература", "#редактура", "#категоризация", "#качество"]}'::jsonb,ARRAY['#K0','#литература','#редактура','#категоризация','#качество']::text[]);
