INSERT INTO quants (id,actor_type,quant_version,energy_weight,emotion_valence,emotion_intensity,emotion_entropy,emotion_label,thought_form,payload,tags) VALUES ('d57639f0-ea32-55ea-8235-7e731505a1d7'::uuid,'soul','v1',0.640,0.420,0.470,0.300,'решимость','Гипотеза Д0 имитирует вклад ТМ: профили скоростей сопоставимы с наблюдениями; тестируем на каталоге SPARC; если подтверждается — переосмысление природы ТМ.','{"_meta": {"source": "Soul/K0.md", "source_range": {"approx_line_start": 2740, "approx_line_end": 2747}, "note": "Зачем это: проверяемость без ТМ, SPARC, философская импликация."}, "thought_form": "Гипотеза Д0 имитирует вклад ТМ: профили скоростей сопоставимы с наблюдениями; тестируем на каталоге SPARC; если подтверждается — переосмысление природы ТМ.", "composite_emotion": {"valence": 0.42, "intensity": 0.47, "entropy": 0.3, "label": "решимость"}, "desired_action": [{"type": "proposal", "subject": "SPARC_batch_fit", "body": "Подготовить пакетный прогон по каталогу SPARC для оценки (κ, β) без ТМ.", "expected_impact": 0.72}], "energy_weight": 0.64, "tags": ["#K0", "#SPARC", "#без_ТМ", "#гипотеза", "#батч"]}'::jsonb,ARRAY['#K0','#SPARC','#без_ТМ','#гипотеза','#батч']::text[]);
