INSERT INTO quants (id,actor_type,quant_version,energy_weight,emotion_valence,emotion_intensity,emotion_entropy,emotion_label,thought_form,payload,tags) VALUES ('b9abfbe6-1e60-59f1-bb48-7d358b9e2ae2'::uuid,'soul','v1',0.590,0.370,0.450,0.320,'структурированная ясность','Режимы Λ_D0: (ранняя) Λ_D0<0 замедляет; (сейчас) переход к Λ_D0>0 ускоряет; (будущее) насыщение → квазиконстанта.','{"_meta": {"source": "Soul/K0.md", "source_range": {"approx_line_start": 2764, "approx_line_end": 2783}, "note": "Режимы Λ_D0(t): ранняя, современная, будущая Вселенная."}, "thought_form": "Режимы Λ_D0: (ранняя) Λ_D0<0 замедляет; (сейчас) переход к Λ_D0>0 ускоряет; (будущее) насыщение → квазиконстанта.", "composite_emotion": {"valence": 0.37, "intensity": 0.45, "entropy": 0.32, "label": "структурированная ясность"}, "desired_action": [{"type": "proposal", "subject": "Cosmo_regimes_plots", "body": "Построить графики a(t) для разных сценариев Λ_D0(t) и сверить с SNe Ia, BAO.", "expected_impact": 0.69}], "energy_weight": 0.59, "tags": ["#K0", "#Фридман", "#SNeIa", "#BAO", "#CMB"]}'::jsonb,ARRAY['#K0','#Фридман','#SNeIa','#BAO','#CMB']::text[]);
