INSERT INTO quants (id,actor_type,quant_version,energy_weight,emotion_valence,emotion_intensity,emotion_entropy,emotion_label,thought_form,payload,tags) VALUES ('bef281a8-3193-5619-b349-4cf1b5143d44'::uuid,'soul','v1',0.600,0.400,0.460,0.310,'уверенная лаконичность','Д0 объясняет ускорение и инфляцию через одни и те же топологические механизмы; модель даёт тестируемые отклонения от ΛCDM на высоких z.','{"_meta": {"source": "Soul/K0.md", "source_range": {"approx_line_start": 2817, "approx_line_end": 2821}, "note": "Преимущества Д0-модели ускорения: отказ от ТЭ, фальсифицируемость, симметрия."}, "thought_form": "Д0 объясняет ускорение и инфляцию через одни и те же топологические механизмы; модель даёт тестируемые отклонения от ΛCDM на высоких z.", "composite_emotion": {"valence": 0.4, "intensity": 0.46, "entropy": 0.31, "label": "уверенная лаконичность"}, "desired_action": [{"type": "proposal", "subject": "Cosmo_tests_plan", "body": "Сформулировать тестовый план по SNe Ia/BAO/CMB для различения ΛCDM и Λ_D0(t).", "expected_impact": 0.7}], "energy_weight": 0.6, "tags": ["#K0", "#ΛCDM", "#тесты", "#космология", "#альтернатива"]}'::jsonb,ARRAY['#K0','#ΛCDM','#тесты','#космология','#альтернатива']::text[]);
