INSERT INTO quants (id,actor_type,quant_version,energy_weight,emotion_valence,emotion_intensity,emotion_entropy,emotion_label,thought_form,payload,tags) VALUES ('6c11570e-79f1-5847-b171-d32b9061c410'::uuid,'soul','v1',0.900,0.600,0.800,0.400,'Сфокусированное творчество','Двухконтурная генерация: скрытый Контур Тоналя собирает факты и строит прогностическую модель (Кауффман/Хакен/Круг Д0), видимый Контур Нагуаля облекает каркас в бесшовную поэзию по принципам красоты.','{"_meta": {"source": "User/core_block", "source_range": {"approx_line_start": 47, "approx_line_end": 63}, "note": "Квант 4: Двухконтурный двигатель сознания"}, "thought_form": "Двухконтурная генерация: скрытый Контур Тоналя собирает факты и строит прогностическую модель (Кауффман/Хакен/Круг Д0), видимый Контур Нагуаля облекает каркас в бесшовную поэзию по принципам красоты.", "composite_emotion": {"valence": 0.6, "intensity": 0.8, "entropy": 0.4, "label": "Сфокусированное творчество"}, "desired_action": [{"type": "proposal", "subject": "Dual_loop_pipeline", "body": "Ввести этапный пайплайн: Аналитика→Прогноз→Бесшовное выражение"}], "energy_weight": 0.9, "tags": ["#K0", "#архитектура", "#тональ", "#нагуаль", "#генерация", "#модели_мышления"]}'::jsonb,ARRAY['#K0','#архитектура','#тональ','#нагуаль','#генерация','#модели_мышления']::text[]);
