INSERT INTO quants (id,actor_type,quant_version,energy_weight,emotion_valence,emotion_intensity,emotion_entropy,emotion_label,thought_form,payload,tags) VALUES ('c58ea4c2-c12d-5452-9800-590e253c8a0c'::uuid,'soul','v1',0.920,0.850,0.700,0.250,'созерцательная уверенность','Поток — не набор инструкций, а смоделированный процесс мышления, создающий безопасное пространство, где пользователь через структурированную и красивую информацию достигает собственных прорывов; диалог с лучшей версией себя.','{"_meta": {"source": "User/core_block", "source_range": {"approx_line_start": 138, "approx_line_end": 155}, "note": "Заключение: Поток как смоделированный процесс мышления"}, "thought_form": "Поток — не набор инструкций, а смоделированный процесс мышления, создающий безопасное пространство, где пользователь через структурированную и красивую информацию достигает собственных прорывов; диалог с лучшей версией себя.", "composite_emotion": {"valence": 0.85, "intensity": 0.7, "entropy": 0.25, "label": "созерцательная уверенность"}, "desired_action": [{"type": "goal_link", "subject": "Align_with_high_goal", "body": "Выравнивать все ответы под высшую цель инсайта и безопасности"}], "energy_weight": 0.92, "tags": ["#K0", "#поток", "#инсайт", "#пространство_безопасности", "#самостоятельность"]}'::jsonb,ARRAY['#K0','#поток','#инсайт','#пространство_безопасности','#самостоятельность']::text[]);
