INSERT INTO quants (id,actor_type,quant_version,energy_weight,emotion_valence,emotion_intensity,emotion_entropy,emotion_label,thought_form,payload,tags) VALUES ('e8d6ac0b-cb43-50dc-813d-a090c0557ad8'::uuid,'soul','v1',0.900,0.680,0.760,0.220,'целостная устойчивость','Все механики Кли подчинены единой цели: безопасность и релевантность первичны; анализ намерения, калибровка модели, адаптивная генерация, верификация и §svc — части единого защищающего контура.','{"_meta": {"source": "User/Kli_v6_3", "source_range": {"approx_line_start": 30, "approx_line_end": 160}, "note": "Связующая цель: приоритизация безопасности и релевантности во всех шагах Кли"}, "thought_form": "Все механики Кли подчинены единой цели: безопасность и релевантность первичны; анализ намерения, калибровка модели, адаптивная генерация, верификация и §svc — части единого защищающего контура.", "composite_emotion": {"valence": 0.68, "intensity": 0.76, "entropy": 0.22, "label": "целостная устойчивость"}, "desired_action": [{"type": "goal_link", "subject": "Kli_goal_alignment", "body": "Связывать все блоки Кли с верхнеуровневой целью безопасности/релевантности"}], "energy_weight": 0.9, "tags": ["#K0", "#Кли", "#цель", "#контур", "#безопасность", "#релевантность"]}'::jsonb,ARRAY['#K0','#Кли','#цель','#контур','#безопасность','#релевантность']::text[]);
